// Brief paraphrases; the linked wiki contains the full reference.
const source = 'https://wod.fandom.com/ru/wiki/Архетипы';
export const archetypes = {
  'Автократ': ['Стремится управлять другими. Воля: установить контроль над группой.', 'Автократ'],
  'Традиционалист': ['Доверяет проверенным обычаям. Воля: доказать преимущество старого способа.', 'Традиционалист'],
  'Одиночка': ['Предпочитает самостоятельность. Воля: добиться важного результата без чужой помощи.', 'Одиночка'],
  'Фанатик': ['Посвящает себя одной цели. Воля: заметно приблизить её осуществление.', 'Фанатик'],
  'Проповедник': ['Живёт своей страстью, увлекает окружающих. Воля: следовать ей или вдохновить другого.', 'Проповедник'],
  'Естествоиспытатель': ['Ищет закономерности. Воля: решить проблему системным, логичным подходом.', 'Естествоиспытатель'],
  'Перфекционист': ['Требует безупречного результата. Воля: достичь цели без заметных изъянов.', 'Перфекционист'],
  'Кающийся грешник': ['Ищет искупления. Воля: совершить поступок, который исправляет прежнюю вину.', 'Кающийся_грешник'],
  'Опекун': ['Заботится о нуждающихся. Воля: успешно защитить другого или помочь ему.', 'Опекун'],
  'Бунтарь': ['Бросает вызов авторитетам. Воля: навредить выбранному противнику или системе.', 'Бунтарь'],
  'Брюзга': ['Скептичен, ожидает худшего. Воля: убедиться в правоте мрачного прогноза.', 'Брюзга'],
  'Плут': ['Прежде всего заботится о себе. Воля: получить выгоду благодаря своей эгоистичной позиции.', 'Плут'],
  'Бон Вивант': ['Ищет яркие удовольствия. Воля: почувствовать полное довольство собой и открыто выразить ликование.', 'Бон_Вивант'],
  'Идеалист': ['Верит в высокие принципы. Воля: поступком приблизить свой идеал.', 'Идеалист'],
  'Конформист': ['Следует признанному лидеру, поддерживает общие цели группы.', 'Конформист']
};
export function archetypeReference(name) {
  const item = archetypes[name];
  return { text: item?.[0] || 'Полное описание архетипа доступно в справочнике.', url: `${source}#${encodeURIComponent(item?.[1] || name)}` };
}
